"""Oblique entrance frames with bounded local reconciliation at round corners.

The actual curb is unchanged. Exact miter vectors stay continuous at authored
bends. Only the final original leg next to a round contact fades toward its
unit normal, with zero blending derivatives at both ends. All consumers use
the same normalized ray and physical ray length for clearance and inversion.
"""
from . import curved_corner_nodes as c


def mouth_axis(g,mouths,index):
    normal=c._right(c._vec(g,c._read(g,mouths,'st_cj_tangent',index,'FLOAT_VECTOR')))
    return c._pick(g,c._read(g,mouths,'st_cj_polyline',index,'BOOLEAN'),
                   c._vec(g,c._read(g,mouths,'st_cj_profile_axis',index,'FLOAT_VECTOR')),normal)


def reconcile(g,path,jet,contact,parameter,mouth,rate,normal,normal_derivative,sign,has_middle):
    """One source curb: retain miters, fade only within the contact's own leg."""
    contact_jet=c._jet(g,path,contact,0.,polyline=True,frame_derivatives=True)
    fade_end=g.math('MINIMUM',mouth,contact_jet['Next Knot'])
    span=g.math('MAXIMUM',fade_end-contact,1e-8)
    q=c.bounded(g,(parameter-contact)/span)
    f=q*q*q*(10.+q*(-15.+6.*q));df=30.*q*q*(1.-q)*(1.-q)*rate/span
    f=c.choose(g,has_middle,f,1.);df=c.choose(g,has_middle,df,0.)
    m=c._scale(c._vec(g,jet['Transverse']),sign)
    dm=c._scale(c._vec(g,jet['Transverse Derivative']),sign*rate)
    vector=c._add(normal,c._scale(c._sub(m,normal),f))
    derivative=c._add(normal_derivative,c._add(c._scale(c._sub(dm,normal_derivative),f),c._scale(c._sub(m,normal),df)))
    exact=c._read(g,path,'st_cc_polyline',0,'BOOLEAN')
    return c._pick(g,exact,vector,normal),c._pick(g,exact,derivative,normal_derivative)


def metric(g,vector,derivative):
    length=c._length(g,vector);safe=g.math('MAXIMUM',length,1e-12)
    direction=c._scale(vector,g.math('DIVIDE',1.,safe))
    length_derivative=c._dot(direction,derivative)
    direction_derivative=c._scale(c._sub(derivative,c._scale(direction,length_derivative)),g.math('DIVIDE',1.,safe))
    return direction,direction_derivative,length,length_derivative
